async function wyslijZObsluga(fetchFn) {
  try {
    const odpowiedz = await fetchFn();
    if (odpowiedz.status === 422) return "popraw dane";
    if (!odpowiedz.ok) return "sprobuj pozniej";
    return await odpowiedz.json();
  } catch (err) {
    if (err instanceof TypeError) return "brak polaczenia";
    throw err;
  }
}
function fetch422() {
  return Promise.resolve({ ok: false, status: 422 });
}
wyslijZObsluga(fetch422).then((w) => console.log(w));
// "popraw dane"

async function wyslijZPonawianiem(fetchFn, maxProb) {
  for (let proba = 1; proba <= maxProb; proba++) {
    try {
      const odpowiedz = await fetchFn();
      if (!odpowiedz.ok) throw new Error("HTTP " + odpowiedz.status);
      return odpowiedz;
    } catch (err) {
      if (!(err instanceof TypeError) || proba === maxProb) throw err;
    }
  }
}
