function limitCzasu(ms) {
  return new Promise((resolve, reject) => setTimeout(() => reject(new Error("przekroczono limit czasu wysylki")), ms));
}
async function wyslijZTimeoutem(fetchFn, limitMs) {
  try {
    const odpowiedz = await Promise.race([fetchFn(), limitCzasu(limitMs)]);
    return odpowiedz;
  } catch (err) {
    return { blad: err.message };
  }
}
function wolnyFetch() {
  return new Promise((resolve) => setTimeout(() => resolve({ ok: true }), 500));
}
wyslijZTimeoutem(wolnyFetch, 100).then((w) => console.log(w));
// { blad: "przekroczono limit czasu wysylki" }

